// Extract keyword data from DataForSEO response
const response = $input.first().json;
const tasks = response.tasks || [];
const items = tasks[0]?.result?.[0]?.items || [];

// Format for the AI prompt
const keywordData = items.map(item => ({
  keyword: item.keyword,
  search_volume: item.keyword_info?.search_volume || 0,
  cpc: item.keyword_info?.cpc || 0,
  competition: item.keyword_info?.competition_level || '',
  difficulty: item.keyword_properties?.keyword_difficulty || 'N/A',
  intent: item.search_intent_info?.main_intent || ''
}));

return [{ json: { keywordData: JSON.stringify(keywordData, null, 2) } }];

