// Parse the AI response into individual rows
const aiResponse = $input.first().json.message?.content || $input.first().json.text || '';
let ideas;
try {
  // Extract JSON array from response
  const jsonMatch = aiResponse.match(/\[\s*\{[\s\S]*\}\s*\]/);
  ideas = JSON.parse(jsonMatch ? jsonMatch[0] : aiResponse);
} catch (e) {
  throw new Error('Failed to parse AI response as JSON: ' + e.message);
}

const pillar = $('Set Pillar Config').first().json.pillar;

return ideas.map(idea => ({
  json: {
    status: 'idea',
    pillar,
    primary_keyword: idea.primary_keyword,
    search_volume: '',
    cpc: '',
    difficulty: '',
    intent: idea.intent,
    suggested_title: idea.suggested_title,
    category: idea.category,
    slug: idea.suggested_title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60),
    live_url: '',
    notes: 'Generated by Planner'
  }
}));
